        }
      }
    }
  }catch(e){ console.error('s3 error', e); }
  try{
    const metrics = await cw.send(new ListMetricsCommand({}));
    console.log('metrics', JSON.stringify(metrics, null, 2));
  }catch(e){ console.error('cw error', e); }
}
run();
"

